using Diten.DecisionIntelligenceService.Application.Modules.OutcomeTracking;using Diten.DecisionIntelligenceService.Domain.Modules.OutcomeTracking;using Diten.DecisionIntelligenceService.Persistence.Modules.OutcomeTracking;using Xunit;
public class TransactionTests
{
 static MutationScope Scope()=>new(Guid.NewGuid(),Guid.NewGuid(),"outcome-tracking.outcomes.create","key","hash");static HashSet<Participant> P(Participant b)=>[b,Participant.Receipt,Participant.AuditIntent,Participant.Outbox];
 [Theory][InlineData(Participant.Aggregate)][InlineData(Participant.Version)][InlineData(Participant.Measurement)][InlineData(Participant.Link)]public void Every_semantic_mutation_commits_exact_one(Participant b){var x=new InMemoryOutcomeTransaction();Assert.Equal(200,x.Execute(Scope(),()=>new(200,"ok"),P(b)).Status);Assert.Equal(new(1,1,1,1),x.Snapshot);}
 [Theory][InlineData(Participant.Aggregate)][InlineData(Participant.Version)][InlineData(Participant.Measurement)][InlineData(Participant.Link)][InlineData(Participant.Receipt)][InlineData(Participant.AuditIntent)][InlineData(Participant.Outbox)]public void Every_fault_rolls_back(Participant f){var x=new InMemoryOutcomeTransaction();var b=f is Participant.Aggregate or Participant.Version or Participant.Measurement or Participant.Link?f:Participant.Aggregate;Assert.Throws<InvalidOperationException>(()=>x.Execute(Scope(),()=>new(200,"ok"),P(b),f));Assert.Equal(new(0,0,0,0),x.Snapshot);}
 [Fact]public void Replay_conflict_and_unknown_commit_are_stateful(){var x=new InMemoryOutcomeTransaction();var s=Scope();Assert.Equal(200,x.Execute(s,()=>new(200,"stable"),P(Participant.Aggregate)).Status);Assert.Equal("stable",x.Execute(s,()=>throw new Exception(),P(Participant.Aggregate)).Value);Assert.Equal(409,x.Execute(s with{Hash="changed"},()=>new(200,"bad"),P(Participant.Aggregate)).Status);var u=Scope();var session=x.BeginUnknownCommit(u,new(200,"committed"));x.CommitOnly(session);Assert.Equal("committed",x.Reconcile(u,Reconciliation.Matching).Value);Assert.Equal(409,x.Reconcile(u,Reconciliation.Conflicting).Status);Assert.Equal(503,x.Reconcile(u,Reconciliation.ConfirmedAbsent).Status);Assert.Equal(503,x.Reconcile(u,Reconciliation.Indeterminate).Status);Assert.Equal(2,x.BusinessBodyCalls);Assert.Equal(1,x.CommitOnlyCalls);Assert.Throws<InvalidOperationException>(()=>x.CommitOnly(Guid.NewGuid()));}
 [Fact]public void Tenant_reader_is_non_disclosing(){var t=Guid.NewGuid();var o=new Outcome(Guid.NewGuid(),t,"O","O",OutcomeKind.Quantitative,Guid.NewGuid());var r=new TenantOutcomeReader([o]);Assert.Same(o,r.Find(t,o.Id));Assert.Null(r.Find(Guid.NewGuid(),o.Id));Assert.Null(r.Find(t,Guid.NewGuid()));Assert.Null(r.Find(t,o.Id,_=>false));}
 [Fact]public void Missing_transaction_participant_fails(){var x=new InMemoryOutcomeTransaction();Assert.Throws<InvalidOperationException>(()=>x.Execute(Scope(),()=>new(200,"bad"),new HashSet<Participant>{Participant.Aggregate,Participant.Receipt,Participant.AuditIntent}));Assert.Equal(new(0,0,0,0),x.Snapshot);}
}
